insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('griichngossn', 'Griichngossn', '', '', '', '', 'Griechengasse', '[{"kategorie": "hist.", "text": "\"historische und malerische Gasse im 1. Wiener Gemeindebezirk\" ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Sie gehört zum [[Stubenviertel]] und liegt in der Nähe des [[Schwedenplatzes]] und des [[Fleischmarktes]]"}, {"kategorie": "", "text": "Die Griechengasse erhielt ihren Namen aufgrund der griechischen Gemeinde, die sich im 18. Jahrhundert in diesem Teil Wiens ansiedelte. Viele griechische Kaufleute ließen sich hier nieder und prägten das Viertel mit ihrer Kultur und ihren Geschäften"}, {"kategorie": "", "text": "Die Griechengasse ist eine der ältesten Straßen in Wien und hat ihre mittelalterliche Struktur weitgehend bewahrt. Sie ist bekannt für ihre enge, verwinkelte Struktur und ihre gut erhaltenen historischen Gebäude. Viele der Häuser entlang der Gasse stammen aus der Barockzeit und dem Biedermeier und verleihen der Gasse ein einzigartiges, fast dörfliches Flair mitten in der Großstadt"}]'::jsonb, ''),
  ('griichnkiachn', 'Griichnkiachn', '', '', '', '', 'Griechenkirche', '[{"kategorie": "hist., wörtlich", "text": "\"Griechenkirche zur Heiligen Dreifaltigkeit\""}, {"kategorie": "", "text": "bedeutende griechisch-orthodoxe Kirche beim [[Fleischmarkt]] im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Die Griechenkirche wurde im Jahr 1787 erbaut, nachdem der griechischen Gemeinde in Wien im Jahr 1781 durch das Toleranzpatent von Kaiser Joseph II. das Recht zur Ausübung ihrer Religion gewährt wurde. Die Kirche ist der Heiligen Dreifaltigkeit geweiht und dient als zentrales Gotteshaus für die griechisch-orthodoxe Gemeinde in Wien"}, {"kategorie": "", "text": "Der Innenraum der Kirche ist mit vielen wertvollen Ikonen und liturgischen Gegenständen ausgestattet, die aus verschiedenen Teilen der orthodoxen Welt stammen. Besonders bemerkenswert ist die prächtige Ikonostase, die eine zentrale Rolle im religiösen Leben der Kirche spielt."}]'::jsonb, ''),
  ('fleischmoakt', 'Fleischmoakt', '', '', '', '', 'Fleischmarkt', '[{"kategorie": "hist.", "text": "\"historische Straße im 1. Wiener Gemeindebezirk\" ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Sie liegt im [[Stubenviertel]] und ist ein wichtiger Teil des alten Wiener Stadtzentrums"}, {"kategorie": "", "text": "Der Name \"Fleischmarkt\" geht auf die Funktion dieser Straße als Handelsplatz für Fleischwaren zurück. Seit dem Mittelalter war der Fleischmarkt der zentrale Ort, an dem Fleischer (Metzger) ihre Waren verkauften. Die Fleischbänke, an denen das Fleisch verkauft wurde, gaben dem Platz seinen Namen"}, {"kategorie": "", "text": "Der Fleischmarkt ist ein bedeutendes kulturelles Erbe der Wiener Innenstadt und ein wichtiger Teil des historischen Stadtbilds. Die Verbindung von Geschichte und Moderne macht ihn zu einem zentralen Ort im städtischen Leben Wiens."}]'::jsonb, ''),
  ('schwednplotz', 'Schwednplotz', '', '', '', '', 'Schwedenplatz', '[{"kategorie": "hist.", "text": "\"wichtiger Platz im 1. Wiener Gemeindebezirk\" ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Er bildet einen zentralen Verkehrsknotenpunkt am Rande der historischen Altstadt, liegt am Ufer des [[Donaukanals]] und markiert die Grenze zwischen der Inneren Stadt und der [[Leopoldstadt]] (2. Wiener Gemeindebezirk)"}, {"kategorie": "", "text": "Der Name \"Schwedenplatz\" wurde 1919 vergeben, als Anerkennung der humanitären Hilfe, die Schweden nach dem Ersten Weltkrieg leistete. Zuvor trug der Platz verschiedene Namen, darunter \"Elisabethplatz\", benannt nach Kaiserin Elisabeth"}, {"kategorie": "", "text": "Insgesamt ist der Schwedenplatz ein zentraler und vielseitiger Platz in Wien, der eine wichtige Rolle im städtischen Leben spielt. Er verbindet historische Bedeutung mit modernem Stadtleben und ist sowohl für den öffentlichen Verkehr als auch für kulturelle und soziale Aktivitäten von großer Bedeutung."}]'::jsonb, ''),
  ('schdubnbastei', 'Schdubnbastei', '', '', '', '', 'Stubenbastei', '[{"kategorie": "hist.", "text": "Befestigungsanlage und ein Teil der ehemaligen Stadtmauer von Wien"}, {"kategorie": "", "text": "Sie befand sich im östlichen Teil der [[Inneren]] Stadt, nahe dem heutigen [[Stubenviertel]], und gehörte zu den insgesamt elf Basteien, die die Wiener Innenstadt umgaben"}, {"kategorie": "", "text": "Die Gegend rund um die Stubenbastei ist heute ein Teil des modernen Wiener Stadtbildes, aber die Bezeichnung bleibt ein wichtiges Zeugnis der mittelalterlichen und frühneuzeitlichen Geschichte der Stadt (die Bezeichnung „Stube“ bezog sich ursprünglich auf Versammlungsräume, die von Zünften genutzt wurden)"}]'::jsonb, ''),
  ('schottnring', 'Schottnring', '', '', '', '', 'Schottenring', '[{"kategorie": "wörtlich", "text": "\"Schottenring\" (Abschnitt der [[Wiener]] Ringstraße, zwischen dem [[Dr]].-Karl-Renner-Ring und dem [[Franz-Josefs-Kai]])"}, {"kategorie": "hist.", "text": "Teil der groß angelegten Stadterweiterung, die im 19. Jahrhundert stattfand, als die Wiener Stadtmauern abgerissen wurden, um Platz für die Ringstraße zu schaffen (Der Name \"Schottenring\" stammt vom [[Schottenstift]], auch bekannt als [[Schottenkloster]], das im 12. Jahrhundert von irischen Benediktinermönchen (den \"Schotten\") gegründet wurde. Diese Mönche wurden aufgrund ihrer Herkunft aus dem damaligen \"Scotia Maior\" (heutiges Irland) als \"Schotten\" bezeichnet, was sich auf den Namen des Klosters und schließlich auch auf den Straßennamen übertrug)"}]'::jsonb, ''),
  ('schottngossn', 'Schottngossn', '', '', '', '', 'Schottengasse', '[{"kategorie": "wörtlich", "text": "\"die Gasse beim [[Schottenstift]]\" (Benediktinerkloster an der Schottengasse)"}, {"kategorie": "hist.", "text": "seit dem Mittelalter bestehende Gasse im 1. Wiener Gedmeindebezirk [\"Innere Stadt\"], benannt nach dem Wiener [[Schottenstift]], das an der Schottengasse liegt."}]'::jsonb, ''),
  ('schottnschdift', 'Schottnschdift', '', '', '', '', 'Schottenstift', '[{"kategorie": "wörtlich", "text": "\"Das Stift der Schotten\" (eigentlich: Benediktinerabtei \"Unserer Lieben Frau zu den Schotten\")"}, {"kategorie": "", "text": "\"Schottenkloster\" (gegründet 1155, als Herzog Heinrich II. Jasomirgott iro-schottische Benediktinermönche nach Wien berief [damals hieß \"Irland\" noch \"scotia maior\" (\"Groß-Schottland\")"}, {"kategorie": "", "text": "\"Schottenkirche\" (Klosterkirche der Benediktinerabtei \"Unserer Lieben Frau zu den Schotten\")"}]'::jsonb, ''),
  ('joppn', 'Joppn', '', '', '', '', 'Joppen', '[{"kategorie": "wörtlich", "text": "\"Joppe\" (vom mittelhochdeutschen \"joppe\"=\"Überzieherjacke\")"}, {"kategorie": "", "text": "ländliche Männerjacke (die anstelle eines Mantels getragen wird und auch als Hausjacke dient), Bauernjacke, Lodenjacke, Schurwolljacke"}]'::jsonb, ''),
