  ('kleckn', 'kleckn', '', '', '', 'Wiener Sprüche, die sitzen!', 'klecken', '[{"kategorie": "wörtlich", "text": "\"klecksen\" (vom mittelhochdeutschen \"klecken\"=\"einen Fleck machen\")"}, {"kategorie": "allg.", "text": "klecksen, spritzen, kleckern"}, {"kategorie": "", "text": "ausreichen, langen hinreichend sein (vom selben mittelhochdeutschen \"klecken\" mit der Bedeutung \"ausreichen\" bzw. \"langen\")"}]'::jsonb, 'Es kleckd sovü wiara Keandl unta hundad Väägl!'),
